package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;
public class NativeEntryDiagnosticProtocolTest {
 static final String N="a".repeat(32),ID="com.microsoft.bing:id/glance_card_container";
 private void add(NativeEntryDiagnosticProtocol.Accumulator a,int i,int parent,String id,String text,String desc,boolean v,boolean e,boolean c){a.add(i,parent,i==0?0:1,0,0,10,10,v,e,c,id,text,desc);}
 @Test public void zeroMatchesIsExplicit(){var a=new NativeEntryDiagnosticProtocol.Accumulator();add(a,0,-1,null,null,null,true,true,true);var p=a.finish();assertEquals(0,p.strictMatches());assertEquals(0,p.candidateTotal());}
 @Test public void twoStrictMatchesNeverCollapse(){var a=new NativeEntryDiagnosticProtocol.Accumulator();add(a,0,-1,ID,null,"Rewards",true,true,true);add(a,1,0,ID,null,"Rewards",true,true,true);assertEquals(2,a.finish().strictMatches());}
 @Test public void textDoesNotPretendToBeDescription(){var a=new NativeEntryDiagnosticProtocol.Accumulator();add(a,0,-1,ID,"Rewards",null,true,true,true);var p=a.finish();assertEquals(1,p.idMatches());assertEquals(1,p.textMatches());assertEquals(0,p.descriptionMatches());assertEquals(0,p.strictMatches());}
 @Test public void fullFunnelFlagsSeparate(){var a=new NativeEntryDiagnosticProtocol.Accumulator();add(a,0,-1,ID,null,"Rewards",false,true,false);var p=a.finish();assertEquals(1,p.intersection());assertEquals(0,p.visible());assertEquals(1,p.enabled());assertEquals(0,p.clickable());assertEquals(0,p.strictMatches());}
 @Test public void exactLabelsOnly(){assertEquals(NativeEntryDiagnosticProtocol.Label.OTHER,NativeEntryDiagnosticProtocol.label("rewards"));assertEquals(NativeEntryDiagnosticProtocol.Label.OTHER,NativeEntryDiagnosticProtocol.label("Rewards "));assertEquals(NativeEntryDiagnosticProtocol.Label.OTHER,NativeEntryDiagnosticProtocol.label("奖励"));}
 @Test public void ancestorsAreActualAndDepthLimited(){var a=new NativeEntryDiagnosticProtocol.Accumulator();for(int i=0;i<5;i++)a.add(i,i-1,i,0,0,10,10,true,true,true,null,i==4?"Rewards":null,null);var p=a.finish();assertEquals(4,p.outputTotal());assertEquals(1,p.candidates().get(0).index());assertEquals(NativeEntryDiagnosticProtocol.Role.ANCESTOR_ONLY,p.candidates().get(0).role());assertEquals(3,p.candidates().get(3).parent());}
 @Test public void capNeverTruncatesCounts(){var a=new NativeEntryDiagnosticProtocol.Accumulator();for(int i=0;i<30;i++)add(a,i,i==0?-1:0,ID,null,"Rewards",true,true,true);var p=a.finish();assertEquals(30,p.strictMatches());assertEquals(30,p.candidateTotal());assertEquals(30,p.outputTotal());assertEquals(16,p.candidates().size());assertTrue(p.truncated());assertEquals(NativeEntryDiagnosticProtocol.Role.BOTH,p.candidates().get(0).role());}
 @Test public void roundTripAndNoRawLeak(){var a=new NativeEntryDiagnosticProtocol.Accumulator();add(a,0,-1,ID,"PRIVATE_ORDINARY_TEXT","Rewards",true,true,true);var r=new NativeEntryDiagnosticProtocol.Report(N,100,110,120,NativeEntryDiagnosticProtocol.Reason.OK,NativeEntryDiagnosticProtocol.Cleanup.CONFIRMED,8,4,0,a.finish());String s=NativeEntryDiagnosticProtocol.encode(r);assertFalse(s.contains("PRIVATE"));assertFalse(s.contains(ID));assertEquals(r,NativeEntryDiagnosticProtocol.parse(s,N,8,90,200,130));assertFalse(r.summary(false).contains("Candidate"));assertFalse(r.summary(false).contains("idMatches"));assertTrue(r.summary(true).contains("counterAuthority=false"));}
 @Test public void wrongIdentityTimeAndExtraFieldsRejected(){var a=new NativeEntryDiagnosticProtocol.Accumulator();add(a,0,-1,null,null,null,true,true,true);String s=NativeEntryDiagnosticProtocol.encode(new NativeEntryDiagnosticProtocol.Report(N,100,110,120,NativeEntryDiagnosticProtocol.Reason.OK,NativeEntryDiagnosticProtocol.Cleanup.CONFIRMED,8,4,0,a.finish()));assertThrows(IllegalArgumentException.class,()->NativeEntryDiagnosticProtocol.parse(s,"b".repeat(32),8,90,200,130));assertThrows(IllegalArgumentException.class,()->NativeEntryDiagnosticProtocol.parse(s,N,9,90,200,130));assertThrows(IllegalArgumentException.class,()->NativeEntryDiagnosticProtocol.parse(s,N,8,90,120,130));assertThrows(IllegalArgumentException.class,()->NativeEntryDiagnosticProtocol.parse(s+"|extra",N,8,90,200,130));}
 @Test public void budgetsRejectOverflow(){var a=new NativeEntryDiagnosticProtocol.Accumulator();assertThrows(IllegalArgumentException.class,()->add(a,0,-1,null,"x".repeat(2049),null,true,true,true));}
 @Test public void lateRewardsHasPriorityOverIdOnlyRows(){var a=new NativeEntryDiagnosticProtocol.Accumulator();add(a,0,-1,null,null,null,true,true,true);for(int i=1;i<25;i++)add(a,i,0,ID,null,null,true,true,true);add(a,25,0,null,"Rewards",null,true,true,false);var p=a.finish();assertEquals(25,p.candidateTotal());assertEquals(26,p.outputTotal());assertTrue(p.truncated());assertTrue(p.candidates().stream().anyMatch(c->c.index()==25));assertTrue(p.candidates().stream().anyMatch(c->c.index()==0));}
}
